WITH valid AS (SELECT *, CASE WHEN event_type IN ('add_to_cart', 'search') THEN 'Core' ELSE 'Other' END event_type_group, COALESCE(page, 'OTHER') resolved_page FROM web_events WHERE event_time > DATE '2023-07-06'), deduped AS (SELECT id, event_type, event_time, duration_sec, resolved_page FROM (SELECT *, ROW_NUMBER() OVER (PARTITION BY page, session_id ORDER BY duration_sec DESC NULLS LAST, id) AS latest_rank FROM valid) ranked WHERE latest_rank = 1), gaps AS (SELECT *, CASE WHEN LAG(event_time) OVER (PARTITION BY event_type ORDER BY event_time, id) IS NULL OR event_time > LAG(event_time) OVER (PARTITION BY event_type ORDER BY event_time, id) + INTERVAL '30' DAY THEN 1 ELSE 0 END AS is_new_session FROM deduped), sessions_web_events AS (SELECT *, SUM(is_new_session) OVER (PARTITION BY event_type ORDER BY event_time, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS burst_id FROM gaps), with_prev AS (SELECT *, LAG(event_time) OVER (PARTITION BY event_type ORDER BY event_time, id) AS prev_event_time FROM sessions_web_events), with_gaps AS (SELECT *, CASE WHEN prev_event_time IS NULL OR event_time > prev_event_time + INTERVAL '30' DAY THEN 1 ELSE 0 END AS new_group_flag FROM with_prev), islands AS (SELECT *, SUM(new_group_flag) OVER (PARTITION BY event_type ORDER BY event_time, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS session_id FROM with_gaps), with_windows AS (SELECT *, NTILE(5) OVER w_hist burst_id_bucket, LAG(session_id, 1) OVER (PARTITION BY event_type ORDER BY event_time, id) prev_session_id, SUM(is_new_session) OVER w_ordered cumulative_is_new_session FROM islands WINDOW w_hist AS (PARTITION BY event_type ORDER BY burst_id, id), w_ordered AS (PARTITION BY event_type ORDER BY prev_event_time, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW)), valid_web_events AS (SELECT id, event_type, duration_sec, resolved_page, burst_id, new_group_flag, session_id, burst_id_bucket, cumulative_is_new_session, ROUND(burst_id * 1.15, 2) burst_id_adjusted FROM with_windows WHERE event_time > TIMESTAMP '2023-06-29 17:00:00' AND prev_event_time >= '2024-05-28') SELECT event_type, APPROX_PERCENTILE(session_id, ARRAY(0.25, 0.5, 0.75)) AS session_id_quartiles, SUM(duration_sec) FILTER (WHERE event_type = 'page_view') AS page_view_total_duration_sec, SORT_ARRAY(COLLECT_SET(event_type)) AS event_type_list, APPROX_PERCENTILE(duration_sec, ARRAY(0.25, 0.5, 0.75)) AS duration_sec_quartiles FROM valid_web_events GROUP BY 1 HAVING SUM(duration_sec) FILTER (WHERE event_type = 'page_view') >= 0;
